<script setup lang="ts">
// FR-DASH-001 / D18-API-044,045 / TC-DASH-001..004
import {ref,computed,onMounted} from 'vue';import {get,errorText,type Row,type Page} from '../../api/implemented';import {useAuthStore} from '../../stores/auth';
interface Window{from:string;to:string;asOf:string;orgIds:string[];timeZone:string}
interface Metric{code:string;name:string;unit:string;value:number|null;status:string;reason:string|null;numerator:number;denominator:number;excludedCount:number;formula:string}
interface Trend{date:string;issues:number;closed:number;batches:number;scanned:number;failed:number}
interface Dashboard{window:Window;generatedAt:string;metricVersion:string;cards:Record<string,number>;metrics:Metric[];orderStates:{status:string;count:number}[];assetClasses:{classification:string;count:number}[];trend:Trend[]}
const auth=useAuthStore(),data=ref<Dashboard|null>(null),error=ref(''),busy=ref(false),orgId=ref(''),days=ref('30'),details=ref<Page|null>(null),selected=ref(''),page=ref(1);let appliedOrg='';
const cards=[{key:'assetTotal',name:'数据资产',code:'ASSETS'},{key:'openIssues',name:'待治理问题',code:'OPEN_ISSUES'},{key:'openOrders',name:'未关闭工单',code:'OPEN_ORDERS'},{key:'completedBatches',name:'窗口内完成检测',code:'DETECTION_BATCHES'},{key:'waitingReviewOrders',name:'待复检工单',code:'WAIT_REVIEW_ORDERS'},{key:'overdueOrders',name:'逾期未关闭',code:'OVERDUE_OPEN_ORDERS'},{key:'scannedRecords',name:'窗口内检测记录',code:''},{key:'failedRecords',name:'窗口内不合格记录',code:''}];
const labels:Record<string,string>={WAIT_DISPATCH:'待派发',WAIT_CLAIM:'待认领',PROCESSING:'处理中',WAIT_REVIEW:'待复检',CLOSED:'已关闭'};
const maxTrend=computed(()=>Math.max(1,...(data.value?.trend.flatMap(t=>[t.issues,t.closed,t.batches])||[]))),totalOrders=computed(()=>data.value?.orderStates.reduce((n,r)=>n+r.count,0)||0),totalAssets=computed(()=>data.value?.assetClasses.reduce((n,r)=>n+r.count,0)||0);
function points(key:'issues'|'closed'|'batches'){const rows=data.value?.trend||[];return rows.map((r,i)=>`${20+i*660/Math.max(1,rows.length-1)},${170-r[key]/maxTrend.value*140}`).join(' ')}
async function load(){busy.value=true;error.value='';details.value=null;selected.value='';try{const to=new Date().toISOString(),from=new Date(Date.now()-Number(days.value)*86400000).toISOString();const requestedOrg=orgId.value;data.value=await get<Dashboard>('D18-API-044',{}, {from,to,asOf:to,...(requestedOrg?{orgId:requestedOrg}:{})});appliedOrg=requestedOrg}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function drill(code:string,newPage=1){if(!data.value)return;busy.value=true;error.value='';try{const w=data.value.window;details.value=await get<Page>('D18-API-045',{}, {metricCode:code,metricVersion:data.value.metricVersion,from:w.from,to:w.to,asOf:w.asOf,...(appliedOrg?{orgId:appliedOrg}:{}),page:String(newPage),size:'20'});selected.value=code;page.value=newPage}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function link(row:Row){if(selected.value==='ASSETS'&&auth.permissions.includes('asset:read'))return '/metadata?asset='+row.id;if(selected.value==='OPEN_ISSUES'&&auth.permissions.includes('quality:read'))return '/issues?issue='+row.id;if(selected.value==='DETECTION_BATCHES'&&auth.permissions.includes('quality:read'))return '/detections';if(!['ASSETS','OPEN_ISSUES','DETECTION_BATCHES'].includes(selected.value)&&auth.permissions.includes('workorder:read'))return '/workorders?order='+row.id;return ''}
onMounted(load);
</script>
<template><section><div class="hero"><div><span class="eyebrow">DATA GOVERNANCE CONTROL CENTER</span><h2>数据治理驾驶舱</h2><p>从资产到闭环，掌握授权范围内的治理进展。</p></div><span class="badge">业务事实 · 当前状态</span></div><form class="actions" @submit.prevent="load"><label>统计窗口<select v-model="days"><option value="7">近7天</option><option value="30">近30天</option><option value="90">近90天</option></select></label><label>组织范围<input v-model="orgId" placeholder="留空为全部授权组织" inputmode="numeric"></label><button :disabled="busy">{{busy?'加载中…':'刷新数据'}}</button></form><p class="error" role="alert">{{error}}</p><template v-if="data"><p class="muted">更新于 {{new Date(data.generatedAt).toLocaleString()}} · UTC时间窗 {{data.window.from.slice(0,10)}} 至 {{data.window.to.slice(0,10)}} · {{data.window.orgIds.length}} 个授权组织</p><div class="metric-grid"><div class="metric-card" v-for="c in cards" :key="c.key"><span>{{c.name}}</span><b>{{Number(data.cards[c.key]||0).toLocaleString()}}</b><button v-if="c.code" @click="drill(c.code)" :disabled="busy">查看明细 ↗</button></div></div><div class="columns"><div class="chart-panel"><h3>治理活动趋势</h3><p class="muted">新增问题（青） · 关闭工单（绿） · 完成检测（紫）</p><svg viewBox="0 0 700 200" role="img" aria-label="按日治理活动趋势"><g stroke="#244766"><path d="M20 30H680M20 100H680M20 170H680"/></g><text x="20" y="20" fill="#86acc9" font-size="11">{{maxTrend}}</text><polyline :points="points('issues')" fill="none" stroke="#54d5ff" stroke-width="2.5"/><polyline :points="points('closed')" fill="none" stroke="#58e0bf" stroke-width="2.5"/><polyline :points="points('batches')" fill="none" stroke="#ad99ff" stroke-width="2.5"/></svg><div class="chart-labels"><span>{{data.trend[0]?.date}}</span><span>{{data.trend[data.trend.length-1]?.date}}</span></div></div><div class="chart-panel"><h3>工单状态分布 <span class="badge">{{totalOrders}} 条</span></h3><div class="bar-row" v-for="r in data.orderStates" :key="r.status"><span>{{labels[r.status]||r.status}}</span><div class="bar-track"><div class="bar-fill" :style="{width:(r.count/Math.max(1,totalOrders)*100)+'%'}"></div></div><strong>{{r.count}}</strong></div><p v-if="!totalOrders" class="muted">当前没有可见工单。</p><h3>资产分级分布</h3><div class="bar-row" v-for="r in data.assetClasses" :key="r.classification"><span>{{r.classification}}</span><div class="bar-track"><div class="bar-fill" :style="{width:(r.count/Math.max(1,totalAssets)*100)+'%'}"></div></div><strong>{{r.count}}</strong></div><p v-if="!totalAssets" class="muted">当前没有可见资产。</p></div></div><h3>治理指标与统计口径</h3><div class="filters"><div class="chart-panel" v-for="m in data.metrics" :key="m.code"><h3>{{m.name}}</h3><strong style="font:26px Consolas">{{m.value===null?'—':Number(m.value).toFixed(2)}} <small>{{m.value===null?'':m.unit}}</small></strong><p class="badge">{{m.reason==='ZERO_DENOMINATOR'?'不适用：分母为零':m.status==='CANDIDATE'?'口径待确认':'已确认口径'}}</p><p class="muted">分子 {{m.numerator}} / 分母 {{m.denominator}} · 排除 {{m.excludedCount}}</p><p class="muted">{{m.formula}}</p><button @click="drill(m.code)" :disabled="busy">查看纳入记录</button></div></div><article v-if="details"><div class="actions"><h3>统计明细 · {{details.total}} 条</h3><button @click="details=null">收起</button></div><p class="muted">沿用看板组织和时间范围；状态为查询时当前状态，跨请求期间业务变化会影响明细。</p><table><thead><tr><th>编号</th><th>名称或记录号</th><th>状态</th><th>时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in details.items" :key="r.id"><td>{{r.id}}</td><td>{{r.name||r.orderNo||r.issueNo||r.batchNo||r.assetCode}}</td><td>{{labels[String(r.status)]||r.status}}</td><td>{{r.closedAt||r.endedAt||r.createdAt}}</td><td><RouterLink v-if="link(r)" :to="link(r)">打开业务页面</RouterLink><span v-else class="muted">只读明细</span></td></tr></tbody></table><div class="actions"><button :disabled="busy||page===1" @click="drill(selected,page-1)">上一页</button><span>第 {{page}} 页</span><button :disabled="busy||page*20>=details.total" @click="drill(selected,page+1)">下一页</button></div></article></template><p v-else-if="busy">正在读取治理记录…</p></section></template>
